<template><section class="page"><header class="head"><div><p class="eyebrow">Caisse sociale</p><h1>Cotisations sociales</h1></div><router-link class="btn" to="/caisse-sociale/cotisations/nouveau">+ Nouveau versement</router-link></header><div class="filters"><label>VOAMAMI<select v-model="voamamiId" @change="load"><option value="">Sélectionner</option><option v-for="v in voamamis" :key="v.id" :value="v.id">{{v.code}} — {{v.nom}}</option></select></label><label>Mois<input v-model="mois" type="month" @change="load"></label></div><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>Membre</th><th>Mois</th><th>Montant</th><th>Date</th><th>Séance</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td>N°{{c.numero_membre}} — {{c.nom}} {{c.prenom||''}}</td><td>{{c.mois_concerne?.slice(0,7)}}</td><td>{{money(c.montant)}}</td><td>{{c.date_paiement?.slice(0,10)}}</td><td>{{c.seance_id||'Hors séance'}}</td></tr><tr v-if="!rows.length"><td colspan="5" class="empty">Aucune cotisation.</td></tr></tbody></table></div></section></template>
<script setup>import{onMounted,ref}from'vue';import caisseSocialeService from'../../service/caisse-sociale.service.js';import voamamiService from'../../service/voamami.service.js';const voamamis=ref([]),voamamiId=ref(''),mois=ref(''),rows=ref([]),error=ref('');const money=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(Number(v||0))+' Ar';onMounted(async()=>{try{const{data}=await voamamiService.getAll();voamamis.value=data.data??[]}catch(e){error.value='Chargement impossible'}});async function load(){if(!voamamiId.value)return;try{const{data}=await caisseSocialeService.getCotisations(voamamiId.value,{mois:mois.value?`${mois.value}-01`:undefined});rows.value=data.data??[]}catch(e){error.value=e.response?.data?.message||'Chargement impossible'}}</script>
<style scoped>.page{max-width:1100px;margin:auto;padding:2rem}.head{display:flex;justify-content:space-between;align-items:end;gap:1rem}.eyebrow{color:#2563eb;text-transform:uppercase;font-size:.75rem;font-weight:700}.btn{background:#2563eb;color:#fff;padding:.7rem 1rem;border-radius:.6rem;text-decoration:none}.filters{display:flex;gap:1rem;margin:1.5rem 0;flex-wrap:wrap}.filters label{display:grid;gap:.3rem;font-weight:600}select,input{padding:.7rem;border:1px solid #cbd5e1;border-radius:.5rem}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:.8rem;border-bottom:1px solid #e2e8f0}th{background:#f8fafc}.error{color:#991b1b;background:#fee2e2;padding:.7rem}.empty{text-align:center;color:#64748b}@media(max-width:600px){.page{padding:1rem}.head{align-items:stretch;flex-direction:column}}
</style>
